labor_capacity = 1650
material_capacity = 1850
fixed_cost = 4500
I = [p['name'] for p in products]
l = {p['name']: p['labor'] for p in products}
m_ = {p['name']: p['material'] for p in products}
p_ = {p['name']: p['price'] for p in products}
v = {p['name']: p['var_cost'] for p in products}
for i in I:
    if i not in l or i not in m_ or i not in p_ or (i not in v):
        raise ValueError(f'Missing data for product {i}')
m = gp.Model('RedBeanClothingFactory')
x = m.addVars(I, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum(((p_[i] - v[i]) * x[i] for i in I)) - fixed_cost, GRB.MAXIMIZE)
m.addConstr(gp.quicksum((l[i] * x[i] for i in I)) <= labor_capacity, name='labor')
m.addConstr(gp.quicksum((m_[i] * x[i] for i in I)) <= material_capacity, name='material')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')